From 2a87e8163481598c706863396a578ea5f20aafa4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:21:06 +0100
Subject: [PATCH] applets/notifications: stop following a widget that is being
 removed

Popups kept following a removed Notifications widget until its removal
became final, so while it could be undone they went to a screen corner.
Forget the widget when it is marked for deletion, adopt it on undo.

BUG: 482411
---
 applets/notifications/main.qml | 12 ++++++++++++
 1 file changed, 12 insertions(+)

diff --git a/applets/notifications/main.qml b/applets/notifications/main.qml
index 8d98753eca..c5ab0334ff 100644
--- a/applets/notifications/main.qml
+++ b/applets/notifications/main.qml
@@ -282,6 +282,18 @@ PlasmoidItem {
         Notifications.Globals.forget(root);
     }

+    Connections {
+        target: Plasmoid
+
+        function onDestroyedChanged(destroyed: bool): void {
+            if (destroyed) {
+                Notifications.Globals.forget(root);
+            } else {
+                Notifications.Globals.adopt(root);
+            }
+        }
+    }
+
     Connections {
         target: Notifications.Globals.popupNotificationsModel

-- 
